with.script:
const needs = JSON.parse(process.env.RESULTS);
const order = ['plan', 'sam-preflight', 'generate', 'assemble', 'catalog-reconcile', 'catalog-correction', 'program-area-revalidation', 'catalog-source-recovery', 'catalog-access-correction', 'catalog-identity-correction', 'catalog-url-correction', 'candidate', 'validate', 'publish', 'pages', 'verify-live'];
const failed = order.find(stage => ['failure', 'cancelled'].includes(needs[stage].result));
const stages = new Set(['auto', 'generate', 'teams', 'backfill', 'reuse', 'catalog-reconcile', 'catalog-correction', 'catalog-projection', 'program-area-revalidation', 'submission-revalidation', 'catalog-source-recovery', 'catalog-access-correction', 'catalog-identity-correction', 'catalog-url-correction', 'validate', 'publish', 'verify']);
const planned = needs.plan.outputs.stage;
const planReason = needs.plan.outputs.reason || 'not reported';
const heldStage = needs.plan.outputs.held_stage || '';
const dailyStatus = needs.plan.outputs.daily_status || '';
const dailyWindow = needs.plan.outputs.daily_window_start || '';
const sourceCompleteness = needs.generate.outputs.source_completeness
  ? (needs.generate.outputs.sources_healthy === 'true' ? 'complete' : 'degraded')
  : 'not assessed for this continuation';
const liveComplete = needs['verify-live'].result === 'success';
const catalogDate = (liveComplete ? needs['verify-live'].outputs.catalog_generated_at : needs.plan.outputs.catalog_generated_at) || '';
const windowTime = Date.parse(dailyWindow), sourceTime = Date.parse(catalogDate);
const fresh = Number.isFinite(windowTime) && Number.isFinite(sourceTime) &&
  sourceTime >= windowTime && sourceTime <= Date.now();
const alreadyCurrent = context.eventName === 'schedule' && needs.plan.result === 'success' &&
  planned === 'noop' && dailyStatus === 'already_current' && fresh;
const scheduledIncomplete = context.eventName === 'schedule' && !(alreadyCurrent || (liveComplete && fresh));
const originalStage = planned === 'program-area-revalidation' && needs.plan.outputs.projection_kind === 'administrative_submission' ?
  'submission-revalidation' : stages.has(planned) ? planned : stages.has(process.env.REQUESTED_STAGE) ? process.env.REQUESTED_STAGE : 'auto';
let candidate = needs.candidate.outputs.candidate_id;
let generationRun = needs.candidate.outputs.candidate_run;
let identitySource = 'selected candidate output';
if (!candidate || !generationRun) {
  const producer = ['generate', 'assemble', 'catalog-reconcile', 'catalog-correction', 'program-area-revalidation', 'catalog-source-recovery', 'catalog-access-correction', 'catalog-identity-correction', 'catalog-url-correction'].find(stage =>
    needs[stage].result === 'success' && needs[stage].outputs.candidate_id);
  if (producer) {
    candidate = needs[producer].outputs.candidate_id; generationRun = needs[producer].outputs.artifact_run || String(context.runId);
    identitySource = `successful ${producer} job; authenticate its retained artifact before reuse`;
  } else {
    const completePlan = needs.plan.outputs.candidate_id && needs.plan.outputs.candidate_run;
    candidate = completePlan ? needs.plan.outputs.candidate_id : process.env.REQUESTED_CANDIDATE_ID;
    generationRun = completePlan ? needs.plan.outputs.candidate_run : process.env.REQUESTED_CANDIDATE_RUN;
    identitySource = 'requested checkpoint selector; artifact authentication still required';
  }
}
const hasCheckpoint = Boolean(candidate && generationRun);
if (!hasCheckpoint) { candidate = 'not persisted'; generationRun = 'none'; identitySource = 'no complete checkpoint selector'; }
const awaiting = needs.publish.outputs.review_ready === 'false';
const next = failed === 'pages' ? 'publish' : failed === 'verify-live' ? 'verify' :
  ['publish', 'validate'].includes(failed) ? failed : failed === 'candidate' && hasCheckpoint ?
  (['publish', 'verify'].includes(originalStage) ? originalStage : 'validate') : originalStage;
const sameRequested = hasCheckpoint && ((candidate === needs.plan.outputs.candidate_id && generationRun === needs.plan.outputs.candidate_run) ||
  (candidate === process.env.REQUESTED_CANDIDATE_ID && generationRun === process.env.REQUESTED_CANDIDATE_RUN));
const receiptRun = needs.validate.result === 'success' ? String(context.runId) :
  sameRequested ? needs.plan.outputs.receipt_run || process.env.REQUESTED_RECEIPT_RUN || 'none' : 'none';
const publicationRun = ['success', 'failure', 'cancelled'].includes(needs.publish.result) ? String(context.runId) :
  sameRequested ? needs.plan.outputs.publication_run || process.env.REQUESTED_PUBLICATION_RUN || 'none' : 'none';
const publicationAttempt = publicationRun === String(context.runId) ? process.env.GITHUB_RUN_ATTEMPT || 'unknown' :
  sameRequested ? needs.plan.outputs.publication_attempt || process.env.REQUESTED_PUBLICATION_ATTEMPT || 'latest retained' : 'none';
const runUrl = `${context.serverUrl}/${context.repo.owner}/${context.repo.repo}/actions/runs/${context.runId}`;
const checkpoint = failed || (awaiting ? 'awaiting_review' : alreadyCurrent ? 'already_current' : planned === 'noop' ?
  (heldStage || scheduledIncomplete ? 'held' : 'noop') : scheduledIncomplete ?
  (liveComplete ? 'stale_catalog' : 'incomplete_verification') : 'completed');
const refreshFailure = scheduledIncomplete ?
  `Scheduled catalog refresh did not establish a fresh verified catalog: ${checkpoint}. Planner reason: ${planReason}` : '';
const retry = failed ? next : awaiting ? 'publish after exact-head review' :
  scheduledIncomplete ? planned === 'noop' ? 'resolve the reported hold before resuming auto' :
  'inspect the retained checkpoint before retry' : 'none';
const body = `Candidate: ${candidate}\nArtifact run: ${generationRun}\nStage: ${checkpoint}\n` +
  `Planned lifecycle stage: ${planned || 'not reported'}\nHeld lifecycle stage: ${heldStage || 'none'}\nPlanner reason: ${planReason}\n` +
  `Daily state: ${dailyStatus || 'not scheduled'}\nDaily window start: ${dailyWindow || 'not applicable'}\nCatalog source timestamp: ${catalogDate || 'unknown'}\nRecovery run: ${needs.plan.outputs.recovery_run || 'none'}\n` +
  `Source completeness: ${sourceCompleteness}\n` +
  (refreshFailure ? `Refresh failure: ${refreshFailure}\n` : '') +
  `Identity source: ${identitySource}\nOriginal lifecycle stage: ${originalStage}\nValidation receipt run: ${receiptRun}\n` +
  `Publication evidence run: ${publicationRun}\nPublication evidence attempt: ${publicationAttempt}\n` +
  `Release-control SHA: ${context.sha}\nProtected publication SHA: ${needs.publish.outputs.merge_sha || 'none confirmed'}\n` +
  `Production mutation: ${needs.publish.outputs.merge_sha ? 'protected publication completed' : needs.publish.result === 'failure' ? 'inspect publication receipt and rollback evidence' : 'none'}\n` +
  `Known-good live identity: publication artifact known-good-live-release.json (when Worker preparation started)\n` +
  `Evidence and safe diagnostics: ${runUrl}#artifacts\nAllowed next retry: ${retry}\n` +
  `Resume the same workflow for pre-candidate failures so its persisted generation checkpoint can be recovered; do not repeat completed expensive work.\n` +
  `A persisted candidate must be reused after downstream failure. Authenticate candidate and receipt artifacts before retry; reported selectors alone are not proof. Caches are not release evidence.`;
await core.summary.addRaw(body).write();
if (failed || scheduledIncomplete) {
  if (scheduledIncomplete) core.setFailed(refreshFailure);
  const title = 'Funding Finder release checkpoint failed';
  const {data: issues} = await github.rest.issues.listForRepo({...context.repo, state:'open', per_page:100});
  const existing = issues.find(issue => !issue.pull_request && issue.title === title);
  if (existing) await github.rest.issues.update({...context.repo, issue_number:existing.number, body});
  else await github.rest.issues.create({...context.repo, title, body});
} else if (liveComplete || alreadyCurrent) {
  const {data: issues} = await github.rest.issues.listForRepo({...context.repo, state:'open', per_page:100});
  const recovered = new Set(['Funding Finder release checkpoint failed', 'Automated Grants.gov refresh failed']);
  if (needs.generate.outputs.sources_healthy === 'true') recovered.add('External funding source refresh degraded');
  for (const issue of issues.filter(issue => !issue.pull_request && recovered.has(issue.title))) {
    await github.rest.issues.update({...context.repo, issue_number:issue.number, state:'closed', state_reason:'completed',
      body: body + '\n\nRecovered after exact live verification. A source disabled for documented upstream unavailability is not represented as healthy.'});
  }
}
